59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
108	    }
109	
110	    /**
111	     * Remembers, per already-seen {@code Idempotency-Key}, the id of the owner that key
112	     * originally created, so a retried create with the same key returns that owner instead
113	     * of creating a duplicate. Held in memory for the application's lifetime and keyed by the
114	     * raw header value.
115	     */
116	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
121	        boolean hasKey = idempotencyKey != null && !idempotencyKey.isBlank();
122	        if (hasKey) {
123	            Integer existingId = idempotentCreates.get(idempotencyKey);
124	            if (existingId != null) {
125	                Owner existing = this.clinicService.findOwnerById(existingId);
126	                if (existing != null) {
127	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
128	                }
129	            }
130	        }
131	        ResponseEntity<OwnerDto> response = createNewOwner(ownerFieldsDto);
132	        if (hasKey && response.getStatusCode() == HttpStatus.CREATED
133	            && response.getBody() != null && response.getBody().getId() != null) {
134	            idempotentCreates.putIfAbsent(idempotencyKey, response.getBody().getId());
135	        }
136	        return response;
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
142	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
143	        if (currentOwner == null) {
144	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
145	        }
146	        currentOwner.setAddress(ownerFieldsDto.getAddress());
147	        currentOwner.setCity(ownerFieldsDto.getCity());
148	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
149	        currentOwner.setLastName(ownerFieldsDto.getLastName());
150	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
151	        String email = ownerFieldsDto.getEmail();
152	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
153	        this.clinicService.saveOwner(currentOwner);
154	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
155	    }
156	
157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Transactional
159	    @Override
160	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
161	        Owner owner = this.clinicService.findOwnerById(ownerId);
162	        if (owner == null) {
163	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
164	        }
165	        owner.setDeleted(true);
166	        this.clinicService.saveOwner(owner);
167	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
168	    }
169	
170	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
171	    @Override
172	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        HttpHeaders headers = new HttpHeaders();
178	        Pet pet = petMapper.toPet(petFieldsDto);
179	        owner.setId(ownerId);
180	        pet.setOwner(owner);
181	        pet.getType().setName(null);
182	        this.clinicService.savePet(pet);
183	        PetDto petDto = petMapper.toPetDto(pet);
184	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
185	            .buildAndExpand(pet.getId()).toUri());
186	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
192	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
193	        if (currentOwner != null) {
194	            Pet currentPet = this.clinicService.findPetById(petId);
195	            if (currentPet != null) {
196	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
197	                currentPet.setName(petFieldsDto.getName());
198	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
199	                this.clinicService.savePet(currentPet);
200	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	            }
202	        }
203	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
204	    }
205	
206	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
207	    @Override
208	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
209	        HttpHeaders headers = new HttpHeaders();
210	        Visit visit = visitMapper.toVisit(visitFieldsDto);
211	        Pet pet = new Pet();
212	        pet.setId(petId);
213	        visit.setPet(pet);
214	        this.clinicService.saveVisit(visit);
215	        VisitDto visitDto = visitMapper.toVisitDto(visit);
216	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
217	            .buildAndExpand(visit.getId()).toUri());
218	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
219	    }
220	
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner != null) {
227	            Pet pet = owner.getPet(petId);
228	            if (pet != null) {
229	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
230	            }
231	        }
232	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
233	    }
234	
235	    /**
236	     * Create and persist a brand-new owner from the supplied fields, returning the
237	     * {@code 201 Created} response for it. This gathers the whole create pipeline in one
238	     * place — map the fields, {@link #normalizeNewOwner normalise} them, apply the daily
239	     * and city gates (each with its own rejection status), resolve any household,
240	     * {@link #assignDerivedAttributes derive the create-time attributes} (including the
241	     * household level ceiling that caps the owner's membership level), save, audit and
242	     * build the response with its {@code Location} header — so {@link #addOwner} itself
243	     * stays a thin entry point. An owner joining an existing household is admitted (its
244	     * membership level is capped to one above the household maximum rather than rejected).
245	     *
246	     * @param ownerFieldsDto the owner fields from the request body
247	     * @return {@code 201 Created} with the created owner and its {@code Location} header,
248	     *         or the appropriate rejection status: {@code 400 Bad Request} when the fields
249	     *         are invalid, {@code 429 Too Many Requests} when the day's create cap is
250	     *         reached, or {@code 409 Conflict} when the city is at capacity
251	     */
252	    private ResponseEntity<OwnerDto> createNewOwner(OwnerFieldsDto ownerFieldsDto) {
253	        HttpHeaders headers = new HttpHeaders();
254	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
255	        if (!normalizeNewOwner(owner)) {
256	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
257	        }
258	        if (dailyLimitReached(owner.getRegistrationDate())) {
259	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
260	        }
261	        if (cityIsAtCapacity(owner.getCity())) {
262	            return new ResponseEntity<>(HttpStatus.CONFLICT);
263	        }
264	        owner.setHouseholdId(owner.computeHouseholdId());
265	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
266	        List<Owner> householdMembers = findHouseholdMembers(owner);
267	        boolean joinsExistingHousehold = !householdMembers.isEmpty();
268	        boolean declaredHouseholdMember = joinsExistingHousehold && sharesHousehold;
269	        assignDerivedAttributes(owner, declaredHouseholdMember, householdMembers);
270	        this.clinicService.saveOwner(owner);
271	        auditOwnerCreated(owner);
272	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
273	        headers.setLocation(UriComponentsBuilder.newInstance()
274	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
275	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
276	    }
277	
278	    /**
279	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
280	     * the canonical form each stored value must take: the address is trimmed,
281	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
282	     * telephone is converted to E.164, any email is lower-cased and a missing
283	     * registration date defaults to today. Field-level rejections are reported here
284	     * rather than inline in {@link #addOwner}, and normalisation runs before any
285	     * household comparison so those comparisons see the canonical values.
286	     *
287	     * @param owner the freshly-mapped owner to normalise
288	     * @return {@code true} if the fields are valid, or {@code false} if the address
289	     *         is blank after normalisation, the telephone cannot form a valid
290	     *         E.164 number, or a supplied registration date is later than the
291	     *         server date, in which case the request must be rejected with
292	     *         {@code 400 Bad Request}
293	     */
294	    private boolean normalizeNewOwner(Owner owner) {
295	        if (!normalizeAddressFields(owner)) {
296	            return false;
297	        }
298	        String telephone = Telephones.toE164(owner.getTelephone());
299	        if (telephone == null) {
300	            return false;
301	        }
302	        owner.setTelephone(telephone);
303	        if (owner.getEmail() != null) {
304	            String email = owner.getEmail().toLowerCase();
305	            owner.setEmail(email);
306	            if (emailDomainIsBlocked(email)) {
307	                return false;
308	            }
309	        }
310	        if (!owner.postcodeValidForLocality()) {
311	            return false;
312	        }
313	        if (owner.getRegistrationDate() == null) {
314	            owner.setRegistrationDate(LocalDate.now());
315	        } else if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
316	            return false;
317	        }
318	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
319	        return true;
320	    }
321	
322	    /**
323	     * Normalise the owner's address fields in place to their canonical stored form
324	     * (trimmed, whitespace-collapsed, upper-cased and with common abbreviations
325	     * expanded; see {@link Owner#normalizeAddress(String)}), gathering the whole address
326	     * concern of {@link #normalizeNewOwner} in one place. The structured form is
327	     * preferred: when a non-blank {@code addressLine1} is supplied it (and any
328	     * {@code addressLine2}) is normalised, and the flat {@code address} is composed from
329	     * them — the normalised {@code addressLine1}, with a single space and the normalised
330	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the
331	     * flat {@code address} is normalised on its own, preserving backward compatibility.
332	     * Either way the canonicalised values are written back so every later household
333	     * comparison and read sees them.
334	     *
335	     * @param owner the freshly-mapped owner whose address fields are being normalised
336	     * @return {@code true} once an address is valid and stored, or {@code false} when
337	     *         neither a structured {@code addressLine1} nor a flat {@code address} is
338	     *         present after normalisation, in which case the request must be rejected
339	     *         with {@code 400 Bad Request}
340	     */
341	    private boolean normalizeAddressFields(Owner owner) {
342	        String addressLine1 = Owner.normalizeAddress(owner.getAddressLine1());
343	        if (!addressLine1.isEmpty()) {
344	            owner.setAddressLine1(addressLine1);
345	            String composed = addressLine1;
346	            String addressLine2 = Owner.normalizeAddress(owner.getAddressLine2());
347	            if (!addressLine2.isEmpty()) {
348	                owner.setAddressLine2(addressLine2);
349	                composed = addressLine1 + " " + addressLine2;
350	            }
351	            owner.setAddress(composed);
352	            return true;
353	        }
354	        String address = Owner.normalizeAddress(owner.getAddress());
355	        if (address.isEmpty()) {
356	            return false;
357	        }
358	        owner.setAddress(address);
359	        return true;
360	    }
361	
362	    /**
363	     * Email domains that identify disposable, throw-away mailboxes. An owner whose
364	     * email address is on one of these domains is rejected with {@code 400 Bad
365	     * Request} rather than created.
366	     */
367	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
368	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
369	
370	    /**
371	     * Whether the given (already lower-cased) email address belongs to a disposable
372	     * mailbox domain on the blocklist. The domain is the part after the final
373	     * {@code '@'}; an address without one is treated as having no blocked domain.
374	     *
375	     * @param email the owner's normalised (lower-cased) email address
376	     * @return {@code true} if the email's domain is on the disposable-domain blocklist
377	     */
378	    private static boolean emailDomainIsBlocked(String email) {
379	        int at = email.lastIndexOf('@');
380	        if (at < 0) {
381	            return false;
382	        }
383	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
384	    }
385	
386	    /**
387	     * The fixed list of public holidays on which the clinic is closed. A registration
388	     * date that lands on one of these dates is treated the same as a weekend and rolled
389	     * forward past it (see {@link #rollToBusinessDay(LocalDate)}).
390	     */
391	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
392	        LocalDate.of(2026, 1, 1),
393	        LocalDate.of(2026, 1, 26),
394	        LocalDate.of(2026, 4, 25),
395	        LocalDate.of(2026, 12, 25),
396	        LocalDate.of(2026, 12, 28));
397	
398	    /**
399	     * Roll the given date forward to the next business day when it falls on a weekend or
400	     * a listed public holiday: a Saturday, Sunday or public holiday is advanced one day
401	     * at a time until a non-holiday weekday is reached, while a plain business day is
402	     * returned unchanged. Because rolling off a weekend can land on a holiday (and vice
403	     * versa), the advance repeats until the date is neither. Applied to the effective
404	     * registration date (whether supplied in the request or defaulted to the server date)
405	     * so that every value derived from it uses the adjusted business day.
406	     *
407	     * @param date the effective registration date
408	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
409	     */
410	    private static LocalDate rollToBusinessDay(LocalDate date) {
411	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
412	            date = date.plusDays(1);
413	        }
414	        return date;
415	    }
416	
417	    /**
418	     * Whether the given date falls on a weekend (Saturday or Sunday).
419	     */
420	    private static boolean isWeekend(LocalDate date) {
421	        return switch (date.getDayOfWeek()) {
422	            case SATURDAY, SUNDAY -> true;
423	            default -> false;
424	        };
425	    }
426	
427	    /**
428	     * Find the existing owners that belong to the same household as the given owner,
429	     * i.e. share the same last name (compared case-insensitively with runs of
430	     * whitespace collapsed to a single space) and postcode, and so resolve to the same
431	     * deterministic {@code householdId}. Soft-deleted owners are excluded, so the result
432	     * holds only current household members. Evaluated before the new owner is saved, so
433	     * it reflects only owners that already existed at creation time; an owner joining no
434	     * existing household yields an empty list.
435	     *
436	     * @param owner the candidate owner being created
437	     * @return the current members of the owner's household, empty if none exists
438	     */
439	    private List<Owner> findHouseholdMembers(Owner owner) {
440	        return this.clinicService.findAllOwners().stream()
441	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()))
442	            .filter(existing -> existing.sameHouseholdAs(owner))
443	            .toList();
444	    }
445	
446	    /**
447	     * Assign the owner's computed-at-creation attributes in place: its customer code,
448	     * namesake count, membership number, bulk-signup warning and household size. Unlike
449	     * the {@code @Transient} attributes {@link Owner} recomputes on demand, these are
450	     * derived once here — from the owner's own (already normalised) fields and from the
451	     * wider owner population — and persisted with the owner. Run after normalisation,
452	     * household resolution and the identity-key check, so every value reflects the
453	     * owner's final field values and any household it has joined, and immediately before
454	     * the owner is saved.
455	     *
456	     * <p>Ordering matters: the customer code is assigned first because the membership
457	     * number is built from it.
458	     *
459	     * @param owner the candidate owner being created, after household resolution
460	     * @param declaredHouseholdMember whether this owner was created as a declared member
461	     *                                of an existing household (it shared an existing
462	     *                                owner's household and set {@code sharesHousehold}),
463	     *                                in which case it is not a suspected duplicate
464	     * @param householdMembers        the existing members of the owner's household at
465	     *                                creation time, used to derive its level ceiling
466	     */
467	    private void assignDerivedAttributes(Owner owner, boolean declaredHouseholdMember,
468	            List<Owner> householdMembers) {
469	        owner.setCustomerCode(deduplicatedCustomerCode(owner));
470	        owner.setNamesakeCount(countNamesakes(owner));
471	        owner.setMembershipNumber(owner.computeMembershipNumber());
472	        owner.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
473	        owner.setHouseholdSize(householdSize(owner));
474	        owner.setMembershipLevelCap(membershipLevelCap(householdMembers));
475	        assignPossibleDuplicate(owner, declaredHouseholdMember);
476	    }
477	
478	    /**
479	     * The household level ceiling to assign to the candidate owner: one above the highest
480	     * {@link Owner#getMembershipLevel() membership level} currently held by an existing
481	     * member of its household, or {@code null} when the household has no existing member
482	     * (so no ceiling applies). This bounds a new owner's reported membership level to at
483	     * most one above its household, keeping households from being outranked at the moment a
484	     * relative joins. Evaluated before the owner is saved, over the members that already
485	     * existed at creation time.
486	     *
487	     * @param householdMembers the existing members of the owner's household
488	     * @return the level ceiling to assign, or {@code null} when uncapped
489	     */
490	    private Integer membershipLevelCap(List<Owner> householdMembers) {
491	        return householdMembers.stream()
492	            .map(Owner::getMembershipLevel)
493	            .max(Comparator.naturalOrder())
494	            .map(max -> max + 1)
495	            .orElse(null);
496	    }
497	
498	    /**
499	     * Compute the customer code to assign to the candidate owner, de-duplicated against
500	     * every existing owner's customer code. The base code is the owner's computed
501	     * {@code <REGION>-<HASH8>} (see {@link Owner#computeCustomerCode()}); when it does not
502	     * already belong to an existing owner it is used unchanged. Otherwise it collides, and
503	     * {@code -<n>} is appended with the smallest integer {@code n} of 2 or more that yields
504	     * a code no existing owner holds, so the returned customer code is unique. Evaluated
505	     * before the owner is saved, so only pre-existing owners are considered.
506	     *
507	     * @param owner the candidate owner being created, after normalisation
508	     * @return the unique (de-duplicated) customer code to assign
509	     */
510	    private String deduplicatedCustomerCode(Owner owner) {
511	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
512	            .map(Owner::getCustomerCode)
513	            .filter(code -> code != null)
514	            .collect(java.util.stream.Collectors.toSet());
515	        String base = owner.computeCustomerCode();
516	        if (!existingCodes.contains(base)) {
517	            return base;
518	        }
519	        int n = 2;
520	        while (existingCodes.contains(base + "-" + n)) {
521	            n++;
522	        }
523	        return base + "-" + n;
524	    }
525	
526	    /**
527	     * Flag the candidate owner as a possible duplicate of an existing owner. A soft
528	     * match is an existing owner that shares this owner's last name (compared
529	     * case-insensitively) and postcode but carries a different (normalised) telephone.
530	     * When such a match exists the owner is still created, but with
531	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the matching
532	     * owner's id; otherwise {@code possibleDuplicate} is false and no match id is
533	     * recorded. The earliest-created matching owner (lowest id) is chosen so the result
534	     * is deterministic. Evaluated before the owner is saved, so only pre-existing owners
535	     * are considered.
536	     *
537	     * <p>A declared household member — one that shared an existing owner's household
538	     * (same last name and postcode) and was admitted because it set
539	     * {@code sharesHousehold} — is never flagged: a declared member is not a suspected
540	     * duplicate, so its {@code possibleDuplicate} is false with no match id.
541	     *
542	     * @param owner the candidate owner being created, after household resolution
543	     * @param declaredHouseholdMember whether the owner is a declared household member
544	     */
545	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
546	        if (declaredHouseholdMember) {
547	            owner.setPossibleDuplicate(false);
548	            owner.setPossibleDuplicateOf(null);
549	            return;
550	        }
551	        String lastName = normalizeName(owner.getLastName());
552	        String postcode = owner.getPostcode();
553	        String telephone = owner.getTelephone();
554	        Optional<Owner> match = this.clinicService.findAllOwners().stream()
555	            .filter(existing -> postcode != null && postcode.equals(existing.getPostcode())
556	                && normalizeName(existing.getLastName()).equals(lastName)
557	                && telephone != null && !telephone.equals(existing.getTelephone()))
558	            .min(Comparator.comparing(Owner::getId));
559	        if (match.isPresent()) {
560	            owner.setPossibleDuplicate(true);
561	            owner.setPossibleDuplicateOf(match.get().getId());
562	        } else {
563	            owner.setPossibleDuplicate(false);
564	            owner.setPossibleDuplicateOf(null);
565	        }
566	    }
567	
568	    /**
569	     * Count how many owners belong to the given owner's household once this create
570	     * completes: the owners that already share its deterministic {@code householdId}
571	     * (derived from last name and postcode) plus the owner being created. Evaluated
572	     * after the owner's {@code householdId} has been assigned. An owner whose
573	     * {@code householdId} matches no existing owner is a household of one.
574	     *
575	     * @param owner the candidate owner being created, after household resolution
576	     * @return the household member count after this create (at least {@code 1})
577	     */
578	    private int householdSize(Owner owner) {
579	        String householdId = owner.getHouseholdId();
580	        if (householdId == null) {
581	            return 1;
582	        }
583	        long existing = this.clinicService.findAllOwners().stream()
584	            .filter(other -> householdId.equals(other.getHouseholdId()))
585	            .count();
586	        return (int) existing + 1;
587	    }
588	
589	    /**
590	     * Count the existing owners that share the given owner's first and last name,
591	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
592	     * before the new owner is saved, so the result reflects only owners that
593	     * already existed at creation time.
594	     *
595	     * @param owner the candidate owner being created
596	     * @return the number of existing namesakes
597	     */
598	    private int countNamesakes(Owner owner) {
599	        String firstName = normalizeName(owner.getFirstName());
600	        String lastName = normalizeName(owner.getLastName());
601	        return (int) this.clinicService.findAllOwners().stream()
602	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
603	                && normalizeName(existing.getLastName()).equals(lastName))
604	            .count();
605	    }
606	
607	    private static String normalizeName(String value) {
608	        return value == null ? "" : value.trim().toLowerCase();
609	    }
610	
611	    /**
612	     * Determine whether the given city has already reached its owner capacity, i.e.
613	     * it already contains 50 or more existing owners (compared case-insensitively
614	     * with surrounding whitespace trimmed). A new owner may not be created in a city
615	     * that is at capacity.
616	     *
617	     * @param city the candidate owner's city
618	     * @return {@code true} if the city already holds 50 or more owners
619	     */
620	    private boolean cityIsAtCapacity(String city) {
621	        String normalizedCity = normalizeName(city);
622	        long count = this.clinicService.findAllOwners().stream()
623	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizedCity))
624	            .count();
625	        return count >= 50;
626	    }
627	
628	    /**
629	     * Determine whether the daily owner-creation limit has already been reached, i.e.
630	     * 100 or more owners already carry the given registration date. A new owner may
631	     * not be created once that day's cap is reached.
632	     *
633	     * @param registrationDate the registration date the new owner would be created with
634	     * @return {@code true} if 100 or more existing owners share that registration date
635	     */
636	    private boolean dailyLimitReached(LocalDate registrationDate) {
637	        long count = this.clinicService.findAllOwners().stream()
638	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
639	            .count();
640	        return count >= 100;
641	    }
642	
643	    /**
644	     * Determine whether more than 80 owners have already been created for the given
645	     * registration date, i.e. strictly more than 80 existing owners carry that date.
646	     * Evaluated before the new owner is saved, so it reflects only owners that
647	     * already existed at creation time.
648	     *
649	     * @param registrationDate the registration date the new owner would be created with
650	     * @return {@code true} if more than 80 existing owners share that registration date
651	     */
652	    private boolean bulkSignupWarning(LocalDate registrationDate) {
653	        long count = this.clinicService.findAllOwners().stream()
654	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
655	            .count();
656	        return count > 80;
657	    }
658	
659	    /**
660	     * Write the create audit record for a freshly-saved owner. Keeps the audit format in
661	     * one place so it stays in step with the owner's identity: it reports the assigned
662	     * customer code alongside the owner's id, registration date, membership level and
663	     * membership number.
664	     *
665	     * @param owner the owner that has just been created and saved
666	     */
667	    private void auditOwnerCreated(Owner owner) {
668	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
669	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
670	            owner.getMembershipNumber());
671	    }
672	}
